CREATE TABLE ipas_sessions (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL CHECK(length(owner_id)>0), mode TEXT NOT NULL CHECK(mode IN ('practice','wrong','import')), question_ids TEXT NOT NULL CHECK(json_valid(question_ids) AND json_type(question_ids)='array' AND json_array_length(question_ids) BETWEEN 1 AND 50), completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0,1)), source_key TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z'), UNIQUE(owner_id,source_key), UNIQUE(id,owner_id));
